        with self.cv:
            self.h += 1
            self._try_form()
            while self.h > 0 and not self._picked('H'):
                pass
        releaseHydrogen()

    def _try_form(self):
        if self.h >= 2 and self.o >= 1:
            self.h -= 2
            self.o -= 1
            self.cv.notify_all()

