#include <mutex>
#include <condition_variable>
#include <functional>
using namespace std;

class Solution {
    mutex m;
    condition_variable cv;
    int h = 0, o = 0;
public:
    void hydrogen(function<void()> releaseHydrogen) {
        unique_lock<mutex> lk(m);
        h++;
        if (h >= 2 && o >= 1) { h -= 2; o -= 1; cv.notify_all(); }
        cv.wait(lk, [&]{ return h >= 0 && (h + o) % 3 == 0 ? false : true; });
        lk.unlock();
        releaseHydrogen();
    }
    void oxygen(function<void()> releaseOxygen) {
        unique_lock<mutex> lk(m);
        o++;
        if (h >= 2 && o >= 1) { h -= 2; o -= 1; cv.notify_all(); }
        cv.wait(lk, [&]{ return true; });
        lk.unlock();
        releaseOxygen();
    }
};

