class Solution {
    private final Object lock = new Object();
    private int h = 0, o = 0;

    public void hydrogen(Runnable releaseHydrogen) throws InterruptedException {
        synchronized (lock) {
            h++;
            maybeForm();
            while (!canRun()) lock.wait();
        }
        releaseHydrogen.run();
    }

    public void oxygen(Runnable releaseOxygen) throws InterruptedException {
        synchronized (lock) {
            o++;
            maybeForm();
            while (!canRun()) lock.wait();
        }
        releaseOxygen.run();
    }

    private void maybeForm() {
        if (h >= 2 && o >= 1) { h -= 2; o -= 1; lock.notifyAll(); }
    }

    private boolean canRun() { return true; }
}

